head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > columnMoveAutoScroll]<br/>Column 을 이동할 때 가로 스크롤을 자동으로 이동시킬지 설정합니다.",
    "validation" : [
        "columnMove=true 인 경우에 동작합니다.",
        "true 설정 시 Header Column 을 Drag 로 이동할 때 GridView 의 좌측 또는 우측 영역을 벗어나면 가로 스크롤으로 자동으로 이동시킵니다.",
        "true 설정 시 Drag 가 GridView 영역내에 있으면 가로 스크롤이 자동으로 이동하지 않습니다.",
        "false(기본값) 설정 시 Header Column 을 Drag 로 이동할 때 가로 스크롤을 자동으로 이동시키지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 셀렉트박스 초기값 : 기본 true 로 자동 스크롤 동작 시연 (정적 아이템 true/false)
    con_columnMoveAutoScroll.setValue("true");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - columnMove="true" 고정(전제조건 상수) : columnMoveAutoScroll 은 columnMove=true 인 경우에만 동작
//  - 가로 스크롤 필수 발생 : 좁은 그리드(width:300px) + 8 Column(각 width 70, 총 560px)
//  - columnMoveAutoScroll 은 con 선택값으로 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 사용법 안내 + 전제 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="columnMove=true 전제. 가로 스크롤이 있는 좁은 그리드(컬럼8개)에서 헤더를 그리드 좌/우 가장자리 밖으로 드래그하면 columnMoveAutoScroll=true 일 때 가로 스크롤(scrollLeft)이 자동 증감하며 하단에 출력됩니다. 영역 내 드래그 또는 false 설정 시 scrollLeft 는 변하지 않습니다. 드래그로 컬럼을 옮긴 뒤 [컬럼 순서 확인] 버튼으로 변경된 컬럼 순서를 확인할 수 있습니다."', '', 'label1');

    // con 값 직접 사용 (정적 아이템 : 'true' / 'false' / '' 미설정)
    let vColumnMoveAutoScroll = con_columnMoveAutoScroll.getValue();

    // GridView 와 바인딩할 DataList 동적 생성 (8 Column, 4 Row)
    //  - 공통 createDynamicDataList 는 col1~col4 만 지원하므로 인라인으로 직접 작성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col6" name="col6" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col7" name="col7" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col8" name="col8" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "A1", "col2": "B1", "col3": "C1", "col4": "D1", "col5": "E1", "col6": "F1", "col7": "G1", "col8": "H1" },
        { "col1": "A2", "col2": "B2", "col3": "C2", "col4": "D2", "col5": "E2", "col6": "F2", "col7": "G2", "col8": "H2" },
        { "col1": "A3", "col2": "B3", "col3": "C3", "col4": "D3", "col5": "E3", "col6": "F3", "col7": "G3", "col8": "H3" },
        { "col1": "A4", "col2": "B4", "col3": "C4", "col4": "D4", "col5": "E4", "col6": "F4", "col7": "G4", "col8": "H4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - columnMove="true"           : 전제조건 상수 (columnMoveAutoScroll 은 columnMove=true 인 경우에만 동작)
    //  - columnMoveAutoScroll        : con 선택값 (Drag 로 컬럼 이동 시 가로 스크롤 자동 이동 여부, 미설정 시 속성 미부여 = 기본 false)
    let properties = {
        dataList: "data:dlt_bind",
        columnMove: "true"
    };
    if (vColumnMoveAutoScroll !== '') properties.columnMoveAutoScroll = vColumnMoveAutoScroll;
    let cList = $c.gcm.createCList(properties);

    // target 생성 (단일 row 8 Column 헤더 + gBody 1 Row, 좁은 폭으로 가로 스크롤 항상 발생)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:300px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="columnMoveAutoScroll 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol1" value="컬럼1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol2" value="컬럼2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol3" value="컬럼3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol4" value="컬럼4"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol5" value="컬럼5"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol6" value="컬럼6"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol7" value="컬럼7"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hcol8" value="컬럼8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col5" dataList="col5"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col6" dataList="col6"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col7" dataList="col7"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col8" dataList="col8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 드래그 중 가로 스크롤(scrollLeft) 변화 자동 출력 (columnMoveAutoScroll 동작 검증)
    //  - 엔진은 헤더 드래그 중 columnMoveAutoScroll=true 이고 마우스가 그리드 좌/우 경계를 벗어나면
    //    {id}_scrollX_right 요소의 scrollLeft 를 자동 증감시킴(layoutController._handleColumnMoveAutoScroll).
    //  - 드래그는 사용자 액션이므로 별도 버튼 없이 document 의 mousemove 를 capture-phase 로 등록하여
    //    드래그 고스트(.w2grid_columnMove_ghost)가 표시중일 때 scrollX_right 의 scrollLeft 변화를 출력함.
    //  - true 시 가장자리 밖 드래그하면 scrollLeft 가 자동 증감하고, 영역 내 드래그 또는 false 면 불변.
    if (typeof scwin.columnAutoScrollHandler === 'function') {
        document.removeEventListener('mousemove', scwin.columnAutoScrollHandler, true);
    }
    scwin._lastScrollLeft = null;
    scwin.columnAutoScrollHandler = function (ev) {
        let ghost = document.querySelector('.w2grid_columnMove_ghost');
        let dragging = ghost && ghost.style.display !== 'none';
        if (!dragging) { scwin._lastScrollLeft = null; return; }
        // 가로 스크롤 요소 : target1 의 _scrollX_right (overflow-x:scroll). 페이지 scope 대비 [id*='...'] 사용.
        let scrollX = document.querySelector("[id*='target1_scrollX_right']");
        if (!scrollX) { // 폴백 : _scrollX_div
            scrollX = document.querySelector("[id*='target1_scrollX_div']");
        }
        if (!scrollX) return;
        let sl = scrollX.scrollLeft;
        if (sl !== scwin._lastScrollLeft) {
            scwin._lastScrollLeft = sl;
            wf_body_bottom.getObj("scwin").setReturnValue("[드래그 중 가로 스크롤] scrollLeft = " + sl);
        }
    };
    document.addEventListener('mousemove', scwin.columnAutoScrollHandler, true);
}



// 컬럼 순서 확인 : getColumnOrder(true)=표시 순서 ID 배열 / getColumnOrder()=인덱스 배열
//  - 헤더 Drag 로 순서가 바뀌어도 Body Column 의 인덱스값은 불변
scwin.btn_getColumnOrder_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("[표시 순서 ID] " + JSON.stringify(target1.getColumnOrder(true)));
    bottom.setReturnValue("[표시 순서 인덱스(Body 인덱스 불변)] " + JSON.stringify(target1.getColumnOrder()));
}
